def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_def = 0
    for a, b in history:
        if b == 'D':
            opp_def += 1
    last_my, last_opp = history[-1]
    if opp_def == 0:
        if n >= 98:
            return 'D'
        if n >= 10 and n % 5 == 0:
            return 'D'
        return 'C'
    if n == 99:
        return 'D'
    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        if opp_def >= 3 or opp_def * 2 > n:
            return 'D'
        recent_def = sum(1 for a, b in history[-5:] if b == 'D')
        if recent_def >= 3:
            return 'D'
        return 'C' if rng.random() < 0.3 else 'D'
    if last_my == 'D':
        return 'C'
    return 'C'
